#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

long long input_n, node_count, total_sum, final_answer;
vector<long long> data_buckets[15];

void create_tree(int level, long long current_num);
void process_value(long long x);

int main() {
    cin >> input_n;
    create_tree(0, 0);
    for (int i = 0; i <= 7; ++i) {
        sort(data_buckets[i].begin(), data_buckets[i].end());
    }
    node_count = 0;
    for (long long i = 1; i <= 9; ++i) {
        process_value(i);
    }
    cout << final_answer << "\n";
    return 0;
}

void create_tree(int level, long long num) {
    if (level == 7) return;
    node_count++;
    long long val = ((node_count - num) % 998244353 + 998244353) % 998244353;
    data_buckets[level].push_back(val);
    total_sum = (total_sum + val) % 1000000007;
    for (int digit = 0; digit <= 9; ++digit) {
        create_tree(level + 1, num * 10 + digit);
    }
}

void process_value(long long x) {
    if (x > input_n) return;
    if (x * 1000000 + 999999 <= input_n && x * 10000000 > input_n) {
        long long current_total = node_count;
        for (int i = 0, factor = 1; i <= 6; ++i, factor *= 10) {
            int size = data_buckets[i].size();
            long long diff = ((current_total - x * factor) % 998244353 + 998244353) % 998244353;
            int pos = (int)(lower_bound(data_buckets[i].begin(), data_buckets[i].end(), 1000000000 - diff) - data_buckets[i].begin());
            final_answer = (final_answer + diff * size + total_sum) % 1000000007;
            final_answer = (final_answer - 998244353 * (size - pos) % 1000000007 + 1000000007) % 1000000007;
            current_total += size;
        }
        return;
    }
    node_count++;
    final_answer = (final_answer + ((node_count - x) % 998244353 + 998244353) % 998244353) % 1000000007;
    for (int digit = 0; digit <= 9; ++digit) {
        process_value(x * 10 + digit);
    }
}
